/* Shared card compositions. Source geometry: PP notes library, research statistics,
   company-brief sections, and detail tables. Spacing is normalized to the shared rhythm;
   Notes are the default card surface. */
(function(F){
 'use strict';
 const E=F.escape,unique=a=>[...new Set(a)];
 for(const n of [3,15,22,26,34,72,156,208])if(!F.tokens['size.'+n])F.addToken('size.'+n,'dimension',n+'px','existing');
 const seed=(id,type,value)=>{if(!F.tokens[id])F.addToken(id,type,value,'existing');};
 for(const n of [7,14,15])seed('radius.'+n,'dimension',n+'px');seed('font.line.17','dimension','17px');seed('font.line.19','dimension','19px');
 seed('shadow.notePaper','shadow','0 6px 2px #00000003,0 3px 2px #00000005,0 2px 2px #00000008,0 0 1px #0000000a');
 const ref=(id,target)=>F.addToken(id,F.tokens[target].type,`{${target}}`,'normalized');
 const aliases={
  'noteCard.radius':'radius.2xl','noteCard.inset':'space.6','noteCard.border':'semantic.border.default','noteCard.borderWidth':'border.width','noteCard.surface':'semantic.surface.default','noteCard.previewSurface':'semantic.surface.subtle','noteCard.previewBorderWidth':'border.width.hairline','noteCard.previewRadius':'radius.xl','noteCard.previewHeight':'size.156','noteCard.paperTop':'size.26','noteCard.paperMaxWidth':'size.208','noteCard.paperPaddingX':'space.20','noteCard.paperPaddingY':'space.20','noteCard.paperShadow':'shadow.notePaper','noteCard.paperIcon':'space.12','noteCard.paperIconGap':'space.8','noteCard.paperFont':'font.size.12','noteCard.paperLine':'font.line.17','noteCard.paperTitleHeight':'size.34','noteCard.paperColor':'semantic.text.placeholder','noteCard.tableCellHeight':'size.15','noteCard.imageHeight':'size.72','noteCard.imageRadius':'radius.5','noteCard.paperLines':'semantic.surface.subtle','noteCard.paperBorder':'color.gray.100','noteCard.infoPaddingX':'space.12','noteCard.infoPaddingY':'space.16','noteCard.identityHeight':'space.48','noteCard.identityGap':'space.8','noteCard.titleFont':'font.size.14','noteCard.titleLine':'font.line.20','noteCard.titleColor':'semantic.text.heading','noteCard.metaGap':'space.8','noteCard.metaMargin':'space.12','noteCard.metaFont':'font.size.12','noteCard.metaLine':'font.line.18','noteCard.metaColor':'semantic.text.secondary','noteCard.companySize':'component.avatar.size.sm','noteCard.companyRadius':'component.avatar.radius.square','noteCard.authorSize':'component.avatar.size.sm','noteCard.authorFont':'component.avatar.font.sm','noteCard.stackFarRadius':'radius.14','noteCard.stackNearRadius':'radius.15','noteCard.stackGap':'space.12','noteCard.stackInset':'space.8','noteCard.stackHeight':'space.20','noteCard.focus':'shadow.focus','noteCard.duration':'motion.duration.normal','noteCard.easing':'motion.easing.standard',
  'statsBar.surface':'semantic.surface.default','statsBar.border':'semantic.border.default','statsBar.borderWidth':'border.width','statsBar.radius':'radius.xl','statsBar.paddingX':'space.16','statsBar.paddingTop':'space.6','statsBar.paddingBottom':'space.20','statsBar.columnPadding':'space.16','statsBar.labelFont':'font.size.11','statsBar.labelLine':'font.line.16','statsBar.label':'semantic.text.secondary','statsBar.valueFont':'font.size.22','statsBar.valueLine':'font.line.28','statsBar.value':'semantic.text.heading','statsBar.valueWeight':'font.weight.500','statsBar.valueTop':'space.8','statsBar.valueBottom':'space.6','statsBar.rowGap':'space.20',
  'informationStack.padding':'space.16','informationStack.gap':'space.8','informationStack.font':'font.size.13','informationStack.line':'font.line.20',
  'informationTable.paddingX':'space.16','informationTable.paddingY':'space.8','informationTable.font':'font.size.13','informationTable.line':'font.line.19','informationTable.headingFont':'font.size.14','informationTable.infoPadding':'space.16'
 };
 for(const [key,target]of Object.entries(aliases))ref('component.'+key,target);
 const keys=prefix=>Object.keys(aliases).filter(k=>k.startsWith(prefix+'.')).map(k=>'component.'+k);
 const buttonTokens=()=>Object.values(F.buttonTokens({variant:'secondary'}));

 const noteItems=[['Research summary','A concise overview of the information gathered so far.'],['Meeting notes','Capture the questions and decisions from the latest discussion.'],['Next steps','List the evidence and follow-up work still needed.']];
 const noteAvatarTokens=(kind)=>F.avatarTokens({variant:'text',shape:kind==='company'?'square':'circle',size:'sm',tone:'blue'});
 F.noteCardTokens=(c={})=>unique(['font.family.sans','font.weight.400','font.weight.500','size.3','space.4','space.8','space.12','space.16','space.20','radius.xs','radius.xl','semantic.surface.default',...keys('noteCard').filter(id=>!['component.noteCard.companySize','component.noteCard.companyRadius','component.noteCard.authorSize','component.noteCard.authorFont'].includes(id)).filter(id=>c.stacked===true||!['stackGap','stackInset','stackHeight','stackFarRadius','stackNearRadius'].some(role=>id.endsWith('.'+role))),...noteAvatarTokens('company'),...noteAvatarTokens('author'),...(c.stacked?Object.values(F.badgeTokens({tone:'neutral',size:'sm'})):[]),...(c.authors?F.avatarGroupTokens({variant:'text',size:'sm',count:3,overflow:0,tone:'blue'}):[])]);
 F.noteCard=(c={})=>{
  const index=Math.abs(Number(c.previewIndex)||0)%noteItems.length,kind=['table','image'].includes(c.noteKind)?c.noteKind:'text',title=c.stacked&&index?noteItems[index][0]:c.title||noteItems[0][0],company=c.company||'AsterGrid',author=c.author||'Alex Morgan';
  const paper=`<span class="pp-note-card-preview"><span class="pp-note-paper"><span class="pp-note-paper-icon">${F.icon(kind==='table'?'grid':'note-filled',12)}</span><span class="pp-note-paper-title">${E(title)}</span>${kind==='table'?`<span class="pp-note-paper-table" aria-hidden="true">${Array.from({length:12},()=>'<i></i>').join('')}</span>`:kind==='image'?'<span class="pp-note-paper-image" aria-hidden="true"></span>':'<span class="pp-note-paper-lines" aria-hidden="true"><i></i><i></i><i></i></span>'}</span></span>`;
  const authors=c.authors?`<span class="pp-note-author-group">${F.avatarGroup({variant:'text',size:'sm',count:3,overflow:0,tone:'blue',groupName:'Note authors'})}</span>`:`<span class="pp-note-author">${F.avatar({variant:'text',shape:'circle',size:'sm',tone:'blue',name:author,initials:author.slice(0,1)})}<span>${E(author.split(' ')[0])}</span></span>`;
  return `<section class="pp-note-card-wrap ${c.stacked?'is-stacked':''}" data-note-card-config="${E(JSON.stringify({...c,previewIndex:index}))}" aria-label="Note card">${c.stacked?`<span class="pp-note-back back-far" aria-hidden="true"></span><span class="pp-note-back back-near" aria-hidden="true"></span><button type="button" class="pp-note-stack-peek" data-note-cycle aria-label="Preview next note for ${E(company)}"><span>${E(noteItems[(index+1)%noteItems.length][0])}</span>${F.icon('chevron',12)}</button>`:''}<details class="pp-note-details"><summary class="pp-note-card">${paper}<span class="pp-note-card-info"><span class="pp-note-card-identity"><span class="pp-note-company">${F.avatar({variant:'text',shape:'square',size:'sm',tone:'blue',name:company,initials:company.slice(0,2)})}</span><strong>${E(c.stacked?company:title)}</strong>${c.stacked?F.badge({tone:'neutral',size:'sm'},'3'):''}</span><span class="pp-note-card-meta"><time>${E(c.date||'8 Oct 2026')}</time>${authors}</span></span></summary><div class="pp-note-preview-content"><section><h4>${E(title)}</h4><p>${E(c.description||noteItems[index][1])}</p></section></div></details><span class="visually-hidden" role="status" data-note-card-status>${c.stacked?'Note '+(index+1)+' of '+noteItems.length:''}</span></section>`;
 };
 const cardWired=new WeakMap();
 F.wireCardPatterns=(root,registerCleanup)=>{
  if(cardWired.has(root))return cardWired.get(root);const timers=new Set(),view=root.ownerDocument?.defaultView||window;
  const cycle=event=>{const button=event.target.closest?.('[data-note-cycle]');if(!button||!root.contains(button)||event.defaultPrevented)return;event.preventDefault();event.stopPropagation();const wrap=button.closest('[data-note-card-config]');let config;try{config=JSON.parse(wrap.dataset.noteCardConfig);}catch{return;}config.previewIndex=(Number(config.previewIndex)||0)+1;const holder=root.ownerDocument.createElement('div');holder.innerHTML=F.noteCard(config);const next=holder.firstElementChild;wrap.replaceWith(next);next.querySelector('[data-note-cycle]')?.focus({preventScroll:true});const reduced=view.matchMedia?.('(prefers-reduced-motion: reduce)').matches||root.closest?.('.preview-paused');if(!reduced){next.classList.add('is-cycling');const timer=view.setTimeout(()=>{next.classList.remove('is-cycling');timers.delete(timer);},200);timers.add(timer);}if(typeof view.CustomEvent==='function')next.dispatchEvent(new view.CustomEvent('forma:note-preview',{bubbles:true,detail:{index:config.previewIndex%noteItems.length}}));};
  root.addEventListener('click',cycle);const cleanup=()=>{root.removeEventListener('click',cycle);timers.forEach(t=>view.clearTimeout(t));cardWired.delete(root);};cardWired.set(root,cleanup);if(registerCleanup)registerCleanup(cleanup);return cleanup;
 };

 const statistics=[['Companies','5','In this result set'],['Average score','90/100','Overall application score'],['Reported revenue','$4.8M','Combined application figures'],['Seed stage','5','Including pre-seed']];
 const statItems=c=>Array.isArray(c.items)&&c.items.length?c.items.slice(0,8).map(item=>Array.isArray(item)?item:[item.label,item.value,item.detail]):statistics;
 F.statsBarTokens=(c={})=>unique(['font.family.sans','font.weight.400',...keys('statsBar').filter(id=>c.variant==='statistics'?!['surface','radius'].some(role=>id.endsWith('.'+role)):c.framed===false?!id.endsWith('.radius'):true)]);
 F.statsBar=(c={})=>{
  const framed=c.variant!=='statistics'&&c.framed!==false,items=statItems(c);
  const strip=`<dl class="pp-stats-values" data-columns="${items.length}" style="--stats-columns:${items.length}">${items.map(([label,value,detail])=>`<div><dt>${E(label)}</dt><dd>${E(value)}</dd>${c.details!==false&&detail?`<dd class="pp-stats-detail"><small>${E(detail)}</small></dd>`:''}</div>`).join('')}</dl>`;
  return c.variant==='statistics'?strip:`<section class="pp-stats-bar ${framed?'is-framed':''}"  aria-label="${E(c.label||'Statistics')}">${strip}</section>`;
 };

 let serial=0;
 const infoTokens=c=>unique(['font.family.sans','font.weight.500','font.weight.600','semantic.border.default','space.4',...['radius','borderWidth','shadow','font','line','headingFont','surface','border','heading','text','inset','padding','headerGap','shell'].map(role=>'component.information.'+role),...(c.tags!==false&&(!Array.isArray(c.tags)||c.tags.length)?Object.values(F.tagTokens({variant:'raised',tone:'neutral'})):[])]);
 const infoHeader=(c,id,fallback)=>F.informationHeader(c.title||fallback,{id,tags:c.tags});
 const footer=c=>c.footer?`<footer class="pp-information-footer"><h4>${E(c.footerTitle||'Note')}</h4><p>${E(typeof c.footer==='string'?c.footer:'Figures and descriptions come from the current application.')}</p></footer>`:'';
 F.stackedInformationTokens=(c={})=>unique([...infoTokens(c),...keys('informationStack')]);
 F.stackedInformation=(c={})=>{
  const id='information-stack-'+(++serial),items=Array.isArray(c.items)&&c.items.length?c.items:[{title:'Product direction',description:'A shared workspace brings the relevant context, evidence, and decisions into one place.'},{title:'What to validate',description:'Check how teams use the workflow and which steps still need manual follow-up.'}];
  return `<section class="pp-information pp-information-card" aria-labelledby="${id}">${infoHeader(c,id,'Information overview')}<div class="pp-information-body pp-information-stack-body">${items.map(item=>`<section class="pp-information-stack-item"><h4>${E(item.title)}</h4><p>${E(item.description)}</p></section>`).join('')}</div>${footer(c)}</section>`;
 };
 F.informationTableTokens=(c={})=>unique([...infoTokens(c),...keys('informationTable').filter(id=>c.info!==false||!id.endsWith('.infoPadding'))]);
 F.informationTable=(c={})=>{
  const id='information-table-'+(++serial),rows=Array.isArray(c.rows)?c.rows:[['Industry','Energy infrastructure'],['Stage','Live'],['Funding round','Seed'],['Reported revenue','$0.8M']];
  return `<section class="pp-information pp-information-card" aria-labelledby="${id}">${infoHeader(c,id,'Company details')}<div class="pp-information-body pp-information-table-body"><table class="pp-information-table"><caption class="visually-hidden">${E(c.title||'Company details')}</caption><thead><tr><th scope="col">Detail</th><th scope="col">From the application</th></tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${E(label)}</th><td>${E(value)}</td></tr>`).join('')}</tbody></table>${c.info!==false?`<aside class="pp-information-table-info"><h4>${E(c.infoTitle||'About these figures')}</h4><p>${E(c.infoText||'Application figures provide context for review. Confirm reporting periods and supporting evidence before comparing companies.')}</p></aside>`:''}</div>${footer(c)}</section>`;
 };
 document.getElementById('project-tokens').textContent=F.tokenCSS();
})(window.Forma);
